<?php defined('APP_BOOTSTRAPPED')||exit;$rows=dball('SELECT o.*,u.full_name customer_name,v.shop_name FROM orders o JOIN users u ON u.id=o.user_id JOIN vendors v ON v.id=o.vendor_id ORDER BY o.id DESC LIMIT 300');?>
<section class="container section page-top"><div class="dash-layout"><?php require __DIR__.'/../partials/side_nav.php';?><div class="dash-main"><div class="eyebrow">ALL ORDERS</div><h1 class="page-title">Toàn bộ <em>đơn hàng</em></h1><p class="muted">Trang giám sát. Xử lý giao hàng do từng người bán thực hiện.</p><div class="panel"><div class="table-wrap"><table><thead><tr><th>Mã đơn</th><th>Khách</th><th>Shop</th><th>Tổng</th><th>Thanh toán</th><th>Trạng thái</th><th>Ngày</th></tr></thead><tbody><?php foreach($rows as $o):?><tr><td><?=h($o['order_code'])?></td><td><?=h($o['customer_name'])?></td><td><?=h($o['shop_name'])?></td><td><?=money($o['total_amount'])?></td><td><?=$o['payment_method']==='cod'?'COD':'QR DEMO'?></td><td><?=h(order_status_label($o['order_status']))?></td><td><?=h($o['created_at'])?></td></tr><?php endforeach;?></tbody></table></div></div></div></div></section>
